// Clean and normalize the query
const query = $input.item.json.query || '';
const practiceId = $input.item.json.practiceId || '';

// Clean query for processing
const cleanQuery = query
  .toLowerCase()
  .trim();

// Extract medical context
const medicalContext = {
  hasAge: /\b(\d+)\s*(year|yr)s?\s*(old)?\b/i.test(query),
  hasGender: /\b(male|female|men|women)\b/i.test(query),
  hasMedicalAid: /\b(medical aid|insurance|coverage)\b/i.test(query),
  hasCondition: /\b(diabetes|hypertension|asthma|covid)\b/i.test(query),
  hasTimeframe: /\b(last|recent|today|yesterday|month|week)\b/i.test(query),
  hasBranch: /\b(branch|location|clinic)\b/i.test(query)
};

return {
  originalQuery: query,
  cleanQuery: cleanQuery,
  medicalContext: medicalContext,
  practiceId: practiceId,
  timestamp: new Date().toISOString()
};

// Format schema for AI consumption
const schemaRows = $input.all();
let schemaText = 'DATABASE SCHEMA:\n\n';
let currentTable = '';

for (const row of schemaRows) {
  const { table_name, column_name, data_type, is_nullable } = row.json;

  if (table_name !== currentTable) {
    if (currentTable) schemaText += '\n';
    schemaText += `TABLE: ${table_name}\n`;
    currentTable = table_name;
  }

  const nullable = is_nullable === 'YES' ? 'NULL' : 'NOT NULL';
  schemaText += `  - ${column_name} (${data_type}, ${nullable})\n`;
}

// Add relationship information
schemaText += `\nKEY RELATIONSHIPS:\n`;
schemaText += `- patients.id -> visits.patient_id\n`;
schemaText += `- patients.id -> medical_aid_details.patient_id\n`;
schemaText += `- patients.id -> appointments.patient_id\n`;
schemaText += `- patients.branch_id -> branches.id\n`;
schemaText += `- visits.id -> medical_records.visit_id\n`;

return {
  schema: schemaText,
  query: $('Clean and Prepare Query').item.json
};

// Parse the AI response
try {
  const aiResponse = $input.item.json.output;

  // Try to extract JSON from the response
  let jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    throw new Error('No JSON found in AI response');
  }

  const parsed = JSON.parse(jsonMatch[0]);

  // Replace PRACTICE_ID placeholder
  const practiceId = $('Clean and Prepare Query').item.json.practiceId;
  parsed.sql = parsed.sql.replace(/PRACTICE_ID/g, practiceId);

  return parsed;
} catch (error) {
  return {
    error: true,
    message: 'Failed to parse AI response: ' + error.message,
    rawResponse: $input.item.json.output
  };
}

// Parse verifier response
try {
  const verifierResponse = $input.item.json.output;
  let jsonMatch = verifierResponse.match(/\{[\s\S]*\}/);

  if (!jsonMatch) {
    throw new Error('No JSON found in verifier response');
  }

  const verified = JSON.parse(jsonMatch[0]);

  // Combine with original data
  const original = $('Parse SQL Response').item.json;

  return {
    sql: verified.sql || original.sql,
    description: verified.description || original.description,
    verified: verified.verified,
    issues: verified.issues || [],
    risk_level: verified.risk_level || 'unknown',
    confidence: original.confidence
  };
} catch (error) {
  return {
    error: true,
    message: 'Failed to parse verifier response',
    verified: false
  };
}

// Format final response
const queryResults = $input.all();
const patientIds = queryResults.map(row => row.json.id).filter(id => id);
const verification = $('Parse Verification').item.json;
const originalQuery = $('Clean and Prepare Query').item.json;

return {
  success: true,
  patientIds: patientIds,
  count: patientIds.length,
  description: verification.description,
  searchQuery: originalQuery.originalQuery,
  confidence: verification.confidence,
  timestamp: new Date().toISOString()
};

// Format error response
const error = $input.item.json;

return {
  success: false,
  error: error.message || 'An error occurred during AI search',
  details: error,
  timestamp: new Date().toISOString()
};
